	n := int(nextInt())
	a := make([]int64, n)
	l, r := 0, 0
	for i := range a {
		a[i] = nextInt()
		if a[i] < a[l] {
			l = i
		}
		if a[i] > a[r] {
			r = i
		}
	}
	// If the lightest is right of the heaviest, one swap moves both at once.
	answer := l + (n - 1 - r)
	if l > r {
		answer--
	}
	fmt.Println(answer)
}

var data []byte
var pos int

func skipSpace() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() []byte {
	skipSpace()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}
